use std::env;
use std::process::ExitCode;

const USAGE: &str = "Usage: roottrace --version | roottrace root <file>";

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();
    match args.as_slice() {
        [flag] if flag == "--version" => {
            println!("roottrace 0.1.0");
            ExitCode::SUCCESS
        }
        [cmd, path] if cmd == "root" => match std::fs::read(path) {
            Ok(data) => {
                let root = merkle_root(&data);
                let mut out = String::with_capacity(64);
                for byte in root {
                    out.push_str(&format!("{byte:02x}"));
                }
                println!("{out}");
                ExitCode::SUCCESS
            }
            Err(err) => {
                eprintln!("roottrace: cannot read {path}: {err}");
                ExitCode::from(1)
            }
        },
        _ => {
            eprintln!("{USAGE}");
            ExitCode::from(2)
        }
    }
}

/// Split the raw file bytes into records on LF (0x0a). The separator is not
/// part of any record. A trailing LF only terminates the last record, so
/// "a\nb" and "a\nb\n" both yield two records; an empty file yields none.
fn split_records(data: &[u8]) -> Vec<&[u8]> {
    if data.is_empty() {
        return Vec::new();
    }
    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
    if data.last() == Some(&b'\n') {
        records.pop();
    }
    records
}

/// RFC 6962 section 2.1 Merkle Tree Hash (SHA-256) over the records of a
/// batch file, in file order.
fn merkle_root(data: &[u8]) -> [u8; 32] {
    let records = split_records(data);
    let leaves: Vec<[u8; 32]> = records
        .iter()
        .map(|record| {
            let mut hasher = Sha256::new();
            hasher.update(&[0x00]);
            hasher.update(record);
            hasher.finish()
        })
        .collect();
    mth(&leaves)
}

/// Merkle Tree Hash over already-hashed leaves.
fn mth(leaves: &[[u8; 32]]) -> [u8; 32] {
    match leaves.len() {
        // MTH({}) = SHA-256()
        0 => Sha256::new().finish(),
        // MTH({d(0)}) = SHA-256(0x00 || d(0)), already computed as the leaf.
        1 => leaves[0],
        n => {
            // k = largest power of two smaller than n.
            let k = if n.is_power_of_two() {
                n / 2
            } else {
                n.next_power_of_two() / 2
            };
            let left = mth(&leaves[..k]);
            let right = mth(&leaves[k..]);
            let mut hasher = Sha256::new();
            hasher.update(&[0x01]);
            hasher.update(&left);
            hasher.update(&right);
            hasher.finish()
        }
    }
}

